Local Ltac slia_consumed_abort :=
  match goal with
  | |- context [(?A + ?s <= ?A \/ ?h <= ?A)%Z] =>
      first [ assert (A < A + s /\ A < h)%Z by (zify_prune; xlia_noeuclid); fail 2 | fail ]
  | |- _ => idtac
  end.
Local Ltac slia ::= first [ exact I | slia_consumed_abort; slia2w ].
