Lemma FieldsOwn_keep : forall LB LB' em (X : Z),
  FieldsOwn LB em -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (forall e d, em !! e = Some d -> e <> X) -> FieldsOwn LB' em.
Proof.
  intros LB LB' em X OWN KEEP NX e d Le. destruct (OWN e d Le) as [p [IN SZ]]. exists p. split; [| exact SZ].
  destruct (KEEP _ IN) as [K | K]; [exact K | exfalso; exact (NX e d Le K)].
Qed.

Lemma MBufOwn_keep : forall LB LB' es (X : Z),
  MBufOwn LB es -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (forall x s, In (x, s) es -> x <> X) -> MBufOwn LB' es.
Proof.
  intros LB LB' es X OWN KEEP NX x s IN. destruct (OWN x s IN) as [p INb]. exists p.
  destruct (KEEP _ INb) as [K | K]; [exact K | exfalso; exact (NX x s IN K)].
Qed.

Lemma SvOwnP_keep : forall LB LB' ptr len (X : Z),
  SvOwnP LB ptr len -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) -> (1 <= len -> ptr <> X) -> SvOwnP LB' ptr len.
Proof.
  intros LB LB' ptr len X [K | (L1 & p & IN)] KEEP NX; [left; exact K | right]. split; [exact L1|]. exists p.
  destruct (KEEP _ IN) as [K | K]; [exact K | exfalso; exact (NX L1 K)].
Qed.

Lemma HdrOwnP_keep : forall LB LB' h (X : Z),
  HdrOwnP LB h -> (forall b, In b LB -> In b LB' \/ blk_addr b = X) ->
  (1 <= hv_ml h -> hv_mp h <> X) -> (1 <= hv_tl h -> hv_tp h <> X) -> HdrOwnP LB' h.
Proof.
  intros LB LB' h X (O1 & O2 & R1 & R2) KEEP N1 N2. split; [| split; [| split; [exact R1 | exact R2]]].
  - eapply SvOwnP_keep; [exact O1 | exact KEEP | exact N1].
  - eapply SvOwnP_keep; [exact O2 | exact KEEP | exact N2].
Qed.
